]}, {"id": "26d7427d-8487-45c0-869d-ca7274ac7d3e", "type": "topic", "title": "Communication Models, Information Theory, and Systems Thinking", "description": "Begins with transmission and systems models, then critiques what they reveal and hide.", "children": [{"id": "3df68ce0-9973-423d-bf2a-9e182354fb83", "type": "subtopic", "title": "Transmission Models", "children": [{"id": "0b776608-75ed-43c1-b208-84ce030a9cad", "type": "concept", "title": "sender"}, {"id": "e2e8c69b-4ce4-4fad-a00f-1880b3a0922c", "type": "concept", "title": "receiver"}, {"id": "122de892-f1b5-46df-ae58-9da0fc7aa900", "type": "concept", "title": "message"}, {"id": "8841014d-bec4-48ea-837e-6a607fbf9684", "type": "concept", "title": "channel"}, {"id": "6d2004ee-b1aa-42d0-8bda-0afd24c37195", "type": "concept", "title": "noise"}, {"id": "86e89d7f-7cb1-40e9-9516-e59beeee489b", "type": "concept", "title": "encoding"}, {"id": "2538e58a-2a59-4974-b26b-ab310c331b05", "type": "concept", "title": "decoding"}, {"id": "babe1620-9eb2-4d57-9b14-f9377242a403", "type": "concept", "title": "Shannon-Weaver"}, {"id": "4cdf8b1c-43d8-47d0-86c1-16100ea02988", "type": "concept", "title": "information theory"}], "description": "Students begin with linear models that explain signal movement, clarity, and breakdown."}, {"id": "c7e290b6-4cbd-4d02-ad55-53d8efcf66a5", "type": "subtopic", "title": "Interaction and Transaction Models", "children": [{"id": "f812ea98-3b28-4565-bca9-9ada6a8f1ad1", "type": "concept", "title": "feedback"}, {"id": "9271588a-8239-4921-8ec1-30a11b1a7878", "type": "concept", "title": "context"}, {"id": "3ce043ce-7f76-4d02-9258-4551e42a6af7", "type": "concept", "title": "simultaneity"}, {"id": "9f7c2427-2bfd-4ee7-86e3-406bb4a0ea22", "type": "concept", "title": "transaction"}, {"id": "d8842771-9ae3-4bc6-bfd8-fe5ea887989d", "type": "concept", "title": "field of experience"}, {"id": "7414ade6-ef3a-4516-82d8-c84d07fdc9a3", "type": "concept", "title": "relational meaning"}, {"id": "15ac58ba-aa92-4067-adb8-90a8